const bands: Record<Cefr, number[]> = { A2: [3,3.5,4], B1: [4.5,5,5.5], B2: [6,6.5,7], C1: [7.5,8] };
export const expandedListeningPlacementItems: (PlacementItem & { source:"ai"; quality:"ai-unreviewed" })[] = Object.entries(passages).flatMap(([level, block]) => block.trim().split("\n").map((row, index) => {
  const f=row.split("|");
  if(f.length!==8||f.some(x=>!x.trim())) throw new Error(`Invalid x3 listening placement ${level}/${index+1}`);
  const [speech,question,answer,a,b,c,explanation,subskill]=f as [string,string,string,string,string,string,string,string];
  const cefr=level as Cefr, band=bands[cefr][index % bands[cefr].length]!;
  const choices=[answer,a,b,c],offset=index%4;
  const serial=Object.keys(passages).indexOf(level)*40+index+1;
  return {id:`fresh-x3-p-l-${String(serial).padStart(3,"0")}`,skill:"listening",text:speech.split("~").join("\n"),question,answer,options:[...choices.slice(offset),...choices.slice(0,offset)],explanation,subskill,band,cefr,difficulty:Number(((band-5)*1.2).toFixed(2)),source:"ai",quality:"ai-unreviewed"};
}));
